const questions=[{reponse:"CSS"},{reponse:"HTML"}];
const reponses=[input("Styles ?"),input("Structure ?")];
let score=0;
for(let i=0;i<questions.length;i++){if(questions[i].reponse.trim().toLowerCase()===reponses[i].trim().toLowerCase())score++;}
console.log("Score:"+score+"/2");

